CREATE OR REPLACE FUNCTION public.social_vault_card_has_path(_card uuid,_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.vault_cards c WHERE c.id=_card AND (split_part(c.image_url,'/vault-images/',2)=_path OR split_part(c.back_image_url,'/vault-images/',2)=_path OR split_part(c.original_image_url,'/vault-images/',2)=_path OR split_part(c.ai_image_url,'/vault-images/',2)=_path OR EXISTS(SELECT 1 FROM jsonb_array_elements(c.image_gallery) v WHERE split_part(v->>'url','/vault-images/',2)=_path))) $$;
CREATE OR REPLACE FUNCTION public.social_post_chain_visible(_post uuid,_visited uuid[] DEFAULT '{}'::uuid[]) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.posts; BEGIN IF _post=ANY(_visited) OR cardinality(_visited)>=16 THEN RETURN false; END IF; SELECT * INTO p FROM public.posts WHERE id=_post; IF NOT FOUND THEN RETURN false; END IF; IF p.user_id=auth.uid() THEN RETURN true; END IF; RETURN p.moderation_status='approved' AND public.social_audience_visible(p.user_id,p.visibility) AND (p.collectible_id IS NULL OR public.social_vault_card_visible(p.collectible_id)) AND (p.image_url IS NULL OR p.image_url NOT LIKE '%/vault-images/%' OR public.social_vault_media_visible(split_part(p.image_url,'/vault-images/',2))) AND (p.shared_post_id IS NULL OR public.social_post_chain_visible(p.shared_post_id,array_append(_visited,_post))); END $$;
CREATE OR REPLACE FUNCTION public.public_profile_by_username(_username text) RETURNS TABLE(id uuid,username text,avatar_url text,public_id text,is_seller boolean,seller_status text,buyer_verified boolean,phone_verified boolean,created_at timestamptz,shop_name text,bio text,banner_url text,accent_color text,social_links jsonb,featured_listing_ids uuid[]) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.username,p.avatar_url,p.public_id,p.is_seller,p.seller_status,NULL::boolean,NULL::boolean,p.created_at,p.shop_name,p.bio,p.banner_url,p.accent_color,p.social_links,p.featured_listing_ids FROM public.profiles p WHERE lower(p.username)=lower(_username) AND public.social_users_unblocked(p.id) $$;
COMMENT ON FUNCTION public.public_profile_by_username(text) IS 'DRAFT ONLY: legacy storefront projection honors blocks and redacts phone/buyer verification; personal profiles must use personal_profile_by_username.';